  type TCommentText,
  type TElement,
  type TSuggestionText,
} from "platejs"
import type { PlateElementProps, RenderNodeWrapper } from "platejs/react"
import { useEditorPlugin, useEditorRef, usePluginOption } from "platejs/react"

import { commentPlugin } from "@/registry/new-york-v4/blocks/editor/components/editor/plugins/comment-kit"
import {
  discussionPlugin,
  type TDiscussion,
} from "@/registry/new-york-v4/blocks/editor/components/editor/plugins/discussion-kit"
import { suggestionPlugin } from "@/registry/new-york-v4/blocks/editor/components/editor/plugins/suggestion-kit"
import { Button } from "@/registry/new-york-v4/ui/button"
import {
  Popover,
