import * as React from "react"
import {
  PlaceholderPlugin,
  PlaceholderProvider,
  updateUploadHistory,
} from "@platejs/media/react"
import { AudioLines, FileUp, Film, ImageIcon, Loader2Icon } from "lucide-react"
import type { TPlaceholderElement } from "platejs"
import { KEYS } from "platejs"
import type { PlateElementProps } from "platejs/react"
import { PlateElement, useEditorPlugin, withHOC } from "platejs/react"
import { useFilePicker } from "use-file-picker"

import { cn } from "@/lib/utils"
import { useUploadFile } from "@/registry/new-york-v4/blocks/editor/hooks/use-upload-file"

const CONTENT: Record<
  string,
  {
    accept: string[]
    content: React.ReactNode
    icon: React.ReactNode
  }
> = {
  [KEYS.audio]: {
    accept: ["audio/*"],
    content: "Add an audio file",
    icon: <AudioLines />,
  },
  [KEYS.file]: {
    accept: ["*"],
    content: "Add a file",
    icon: <FileUp />,
  },
  [KEYS.img]: {
    accept: ["image/*"],
    content: "Add an image",
    icon: <ImageIcon />,
  },
  [KEYS.video]: {
    accept: ["video/*"],
    content: "Add a video",
    icon: <Film />,
  },
}

export const PlaceholderElement = withHOC(
  PlaceholderProvider,
  function PlaceholderElement(props: PlateElementProps<TPlaceholderElement>) {
    const { editor, element } = props

    const { api } = useEditorPlugin(PlaceholderPlugin)

    const { isUploading, progress, uploadedFile, uploadFile, uploadingFile } =
      useUploadFile()

    const loading = isUploading && uploadingFile

    const currentContent = CONTENT[element.mediaType]

    const isImage = element.mediaType === KEYS.img

    const imageRef = React.useRef<HTMLImageElement>(null)

    const { openFilePicker } = useFilePicker({
      accept: currentContent.accept,
      multiple: true,
      onFilesSelected: ({ plainFiles: updatedFiles }) => {
        const firstFile = updatedFiles[0]
        const restFiles = updatedFiles.slice(1)

        replaceCurrentPlaceholder(firstFile)

        if (restFiles.length > 0) {
          editor.getTransforms(PlaceholderPlugin).insert.media(restFiles)
        }
      },
    })

    const replaceCurrentPlaceholder = React.useCallback(
      (file: File) => {
        void uploadFile(file)
        api.placeholder.addUploadingFile(element.id as string, file)
      },
      [api.placeholder, element.id, uploadFile]
    )

    React.useEffect(() => {
      if (!uploadedFile) return

      const path = editor.api.findPath(element)

      editor.tf.withoutSaving(() => {
        editor.tf.removeNodes({ at: path })

        const node = {
          children: [{ text: "" }],
          initialHeight: imageRef.current?.height,
          initialWidth: imageRef.current?.width,
          isUpload: true,
          name: element.mediaType === KEYS.file ? uploadedFile.name : "",
          placeholderId: element.id as string,
          type: element.mediaType!,
          url: uploadedFile.url,
        }

        editor.tf.insertNodes(node, { at: path })

        updateUploadHistory(editor, node)
      })

      api.placeholder.removeUploadingFile(element.id as string)
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [uploadedFile, element.id])

    // React dev mode will call React.useEffect twice
    const isReplaced = React.useRef(false)

    /** Paste and drop */
    React.useEffect(() => {
      if (isReplaced.current) return

      isReplaced.current = true
      const currentFiles = api.placeholder.getUploadingFile(
        element.id as string
      )

      if (!currentFiles) return

      replaceCurrentPlaceholder(currentFiles)

      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isReplaced])

    return (
      <PlateElement className="my-1" {...props}>
        {(!loading || !isImage) && (
          <div
            className={cn(
              "bg-muted hover:bg-primary/10 flex cursor-pointer items-center rounded-sm p-3 pr-9 select-none"
            )}
            onClick={() => !loading && openFilePicker()}
            contentEditable={false}
          >
            <div className="text-muted-foreground/80 relative mr-3 flex [&_svg]:size-6">
              {currentContent.icon}
            </div>
            <div className="text-muted-foreground text-sm whitespace-nowrap">
              <div>
                {loading ? uploadingFile?.name : currentContent.content}
              </div>

              {loading && !isImage && (
                <div className="mt-1 flex items-center gap-1.5">
                  <div>{formatBytes(uploadingFile?.size ?? 0)}</div>
                  <div>–</div>
                  <div className="flex items-center">
                    <Loader2Icon className="text-muted-foreground mr-1 size-3.5 animate-spin" />
                    {progress ?? 0}%
                  </div>
                </div>
              )}
            </div>
          </div>
        )}

        {isImage && loading && (
          <ImageProgress
            file={uploadingFile}
            imageRef={imageRef}
            progress={progress}
          />
        )}

        {props.children}
      </PlateElement>
    )
  }
)

export function ImageProgress({
  className,
  file,
  imageRef,
  progress = 0,
}: {
  file: File
  className?: string
  imageRef?: React.RefObject<HTMLImageElement | null>
  progress?: number
}) {
  const [objectUrl, setObjectUrl] = React.useState<string | null>(null)

  React.useEffect(() => {
    const url = URL.createObjectURL(file)
    setObjectUrl(url)

    return () => {
      URL.revokeObjectURL(url)
    }
  }, [file])

  if (!objectUrl) {
    return null
  }

  return (
    <div className={cn("relative", className)} contentEditable={false}>
      <img
        ref={imageRef}
        className="h-auto w-full rounded-sm object-cover"
        alt={file.name}
        src={objectUrl}
      />
      {progress < 100 && (
        <div className="absolute right-1 bottom-1 flex items-center space-x-2 rounded-full bg-black/50 px-1 py-0.5">
          <Loader2Icon className="text-muted-foreground size-3.5 animate-spin" />
          <span className="text-xs font-medium text-white">
            {Math.round(progress)}%
          </span>
        </div>
      )}
    </div>
  )
}

function formatBytes(
  bytes: number,
  opts: {
    decimals?: number
    sizeType?: "accurate" | "normal"
  } = {}
) {
  const { decimals = 0, sizeType = "normal" } = opts

  const sizes = ["Bytes", "KB", "MB", "GB", "TB"]
  const accurateSizes = ["Bytes", "KiB", "MiB", "GiB", "TiB"]

  if (bytes === 0) return "0 Byte"

  const i = Math.floor(Math.log(bytes) / Math.log(1024))

  return `${(bytes / Math.pow(1024, i)).toFixed(decimals)} ${
    sizeType === "accurate"
      ? (accurateSizes[i] ?? "Bytest")
      : (sizes[i] ?? "Bytes")
  }`
}

