          {isSelectingTable && (
            <div className={blockSelectionVariants()} contentEditable={false} />
          )}
        </div>
      </PlateElement>
    )

    if (readOnly) {
      return content
    }

    return <TableFloatingToolbar>{content}</TableFloatingToolbar>
